// seedOccupiedPorts resolves the default/unscoped environment's ContainerRuntime
// and reseeds nodeClients' port manager with its ListOccupiedPorts view -
// ListOccupiedPorts is daemon-wide and unfiltered by design (see
// docs/container_runtimes/interface_design.md), so any environment's resolved
// runtime reports the same occupancy. See docs/ports_management for why this
// can't happen inside node_clients.NewNodeClients itself.
func seedOccupiedPorts(
	ctx context.Context,
	nodeClients node_clients.NodeClients,
	runtimes container_runtime.RuntimeResolver,
	availablePorts []int,
) error {
	runtime, err := runtimes.Runtime(ctx, "")
	if err != nil {
		return rerrors.Wrap(err, "error resolving container runtime")
	}

	usedPorts, err := runtime.ListOccupiedPorts(ctx)
	if err != nil {
		return rerrors.Wrap(err, "error listing occupied ports")
	}

	nodeClients.PortManagerContainer().Set(ports.NewPortManager(availablePorts, usedPorts))

	return nil
}

func smerdsDropper(smerdService service.ContainerService) func() error {
	return func() error {
		log.Info().Msg("ShutDownOnExit env variable is set to TRUE. Dropping launched smerds")
		log.Info().Msg("Listing launched smerds")

		ctx := context.Background()

		listReq := &velez_api.ListSmerds_Request{}

		smerds, err := smerdService.ListSmerds(ctx, listReq)
		if err != nil {
			return rerrors.Wrap(err, "error listing smerds before dropping")
		}

		names := make([]string, 0, len(smerds.GetSmerds()))

		for _, sm := range smerds.GetSmerds() {
			names = append(names, sm.GetName())
		}

		log.Info().Int("count", len(smerds.GetSmerds())).Strs("names", names).Msg("smerds active")

		dropReq := &velez_api.DropSmerd_Request{
			Uuids: make([]string, len(smerds.GetSmerds())),
		}

		for i := range smerds.GetSmerds() {
			dropReq.Uuids[i] = smerds.GetSmerds()[i].GetUuid()
		}

		log.Info().Int("count", len(smerds.GetSmerds())).Msg("dropping smerds")

		dropSmerds, err := smerdService.DropSmerds(ctx, dropReq)
		if err != nil {
			return rerrors.Wrap(err, "error dropping smerds")
		}

		log.Info().Int("count", len(dropSmerds.GetSuccessful())).Msg("smerds dropped successfully")

		if len(dropSmerds.GetSuccessful()) != 0 {
			log.Info().Strs("dropped", dropSmerds.GetSuccessful()).Msg("dropped smerds")
		}

		if len(dropSmerds.GetFailed()) != 0 {
			log.Error().Int("count", len(dropSmerds.GetFailed())).Msg("smerds failed to drop")

			for _, f := range dropSmerds.GetFailed() {
				log.Error().Str("uuid", f.GetUuid()).Str("cause", f.GetCause()).Msg("error dropping smerd")
			}
		}

		return nil
	}
}

func parseLogLevel(str string) zerolog.Level {
	str = strings.ToLower(str)
	if str == "warning" {
		str = "warn"
	}

	level, err := zerolog.ParseLevel(str)
	if err != nil {
		return zerolog.InfoLevel
	}

	return level
}
